import React, { useState, useEffect, useRef, useCallback } from 'react';
import styles from './Notification.module.css';

function Notification({
                          message,
                          type = 'info',
                          duration = 3000,
                          onClose,
                          showProgress = true
                      }) {
    const [isVisible, setIsVisible] = useState(true);
    const [progress, setProgress] = useState(100);
    const [isPaused, setIsPaused] = useState(false);
    const animationRef = useRef(null);
    const startTimeRef = useRef(null);
    const durationRef = useRef(duration);
    const progressRef = useRef(progress);

    // Обновляем ref при изменении пропса
    useEffect(() => {
        durationRef.current = duration;
    }, [duration]);

    // Используем useCallback для handleClose
    const handleClose = useCallback(() => {
        setIsVisible(false);
        if (onClose) {
            setTimeout(() => onClose(), 300);
        }
    }, [onClose]);

    useEffect(() => {
        if (!isVisible || !showProgress) return;

        const animate = (timestamp) => {
            if (!startTimeRef.current) {
                startTimeRef.current = timestamp;
            }

            if (isPaused) {
                // Если на паузе, просто запрашиваем следующий кадр
                animationRef.current = requestAnimationFrame(animate);
                return;
            }

            const elapsed = timestamp - startTimeRef.current;
            const remaining = Math.max(0, durationRef.current - elapsed);
            const newProgress = (remaining / durationRef.current) * 100;

            setProgress(newProgress);
            progressRef.current = newProgress;

            if (elapsed < durationRef.current) {
                animationRef.current = requestAnimationFrame(animate);
            } else {
                handleClose();
            }
        };

        animationRef.current = requestAnimationFrame(animate);

        return () => {
            if (animationRef.current) {
                cancelAnimationFrame(animationRef.current);
            }
        };
    }, [isVisible, isPaused, showProgress, handleClose]); // ← ДОБАВЛЕНО handleClose

    const handleMouseEnter = () => {
        setIsPaused(true);
        if (startTimeRef.current) {
            // Сохраняем сколько прошло времени
            const elapsed = performance.now() - startTimeRef.current;
            // Корректируем оставшееся время
            durationRef.current = durationRef.current - elapsed;
        }
    };

    const handleMouseLeave = () => {
        // Сбрасываем начальное время для нового отсчета
        startTimeRef.current = performance.now();
        setIsPaused(false);
    };

    if (!isVisible) return null;

    return (
        <div
            className={`${styles.notification} ${styles[type]}`}
            onMouseEnter={handleMouseEnter}
            onMouseLeave={handleMouseLeave}
            onClick={handleClose}
            role="alert"
            aria-live="polite"
        >
            <div className={styles.content}>
                <div className={styles.icon}>
                    {type === 'success' && '✅'}
                    {type === 'error' && '❌'}
                    {type === 'warning' && '⚠️'}
                    {type === 'info' && 'ℹ️'}
                </div>
                <div className={styles.message}>{message}</div>
                <button
                    onClick={(e) => {
                        e.stopPropagation();
                        handleClose();
                    }}
                    className={styles.closeBtn}
                    aria-label="Закрыть"
                >
                    ×
                </button>
            </div>

            {showProgress && (
                <div className={styles.progressBar}>
                    <div
                        className={`${styles.progressFill} ${isPaused ? styles.paused : ''}`}
                        style={{
                            width: `${progress}%`,
                            transition: isPaused ? 'none' : 'width 0.1s linear'
                        }}
                    />
                </div>
            )}
        </div>
    );
}

export default Notification;
